import { IOperatorTheme } from '@game-studio/operator-theme';
import { VueConstructor } from 'vue';
export type SvgIconType = 'arrow' | 'cross' | 'tick';
export type UserPreferenceType = 'checkbox' | 'radio' | 'colour';
export type UserPreferenceValue = string | number | boolean | UserPreferencesObjectValue;
export type UserPreferencesObjectValue = {
    [key: string]: any;
};
export interface IUserPreferenceConfig {
    type: UserPreferenceType;
    key: string;
    label: string;
    options?: Array<ISettingsOption>;
    default?: UserPreferenceValue;
}
export interface IUserPreferences {
    [key: string]: UserPreferenceValue;
    misc: {
        [key: string]: UserPreferenceValue;
    };
}
export interface ISettingsOption {
    text: string;
    value: string | number;
}
export interface ISettingsPluginOptions {
    userId: number | string;
    gameName: string;
    theme: IOperatorTheme;
}
export interface SubMenuEvents {
    open(options: IOpenSubMenuOptions): void;
    close(): void;
}
export interface ISubSettingMenu {
    id: string;
    label: string;
    props?: {
        [key: string]: unknown;
    };
    component: VueConstructor;
}
export interface IOpenSubMenuOptions {
    id: string;
    label?: string;
    nested?: boolean;
    props?: {
        [key: string]: unknown;
    };
}
export interface Events {
    show(): void;
    hide(): void;
    toggle(): void;
    inGameShow(options: IOpenSubMenuOptions): Promise<void>;
}
